      sql`LOWER(TRIM(${schema.searchHistory.query})) = ${normalizedQuery}`,
      sql`${schema.searchHistory.createdAt} >= ${oneDayAgo}`
    ))
    .orderBy(desc(schema.searchHistory.createdAt))
    .limit(1);
  return results[0];
