import type { Express, Request } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { generateToken, comparePassword, authMiddleware, adminMiddleware } from "./utils/auth";
import { upload, extractPdfText, deleteFile } from "./utils/file-processor";
import {
  extractQueryIntent,
  classifyDomain,
  searchInDocuments,
  analyzeImage,
  generateAgricultureResponse,
  analyzePdfDocument,
  askAboutDocument,
  withTimeout,
} from "./utils/openai-service";
import { fetchAgricultureData } from "./utils/external-apis";
import { insertUserSchema, insertSearchHistorySchema, insertApiSettingSchema } from "@shared/schema";
import path from "path";
import fs from "fs/promises";

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

export async function registerRoutes(app: Express): Promise<Server> {

  // Auth routes
  app.post("/api/auth/signup", async (req, res) => {
    try {
      const userData = insertUserSchema.parse(req.body);

      const existingUser = await storage.getUserByEmail(userData.email);
      if (existingUser) {
        return res.status(400).json({ message: "Email already registered" });
      }

      const user = await storage.createUser(userData);
      const token = generateToken({
        userId: user.id,
        email: user.email,
        role: user.role,
      });

      res.json({
        token,
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
        },
      });
    } catch (error: any) {
      res.status(400).json({ message: error.message || "Signup failed" });
    }
  });

  app.post("/api/auth/login", async (req, res) => {
    try {
      const { email, password } = req.body;

      const user = await storage.getUserByEmail(email);
      if (!user) {
        return res.status(401).json({ message: "Invalid credentials" });
      }

      if (!user.isActive) {
        return res.status(403).json({ message: "Account is deactivated" });
      }

      const isValidPassword = await comparePassword(password, user.password);
      if (!isValidPassword) {
        return res.status(401).json({ message: "Invalid credentials" });
      }

      const token = generateToken({
        userId: user.id,
        email: user.email,
        role: user.role,
      });

      res.json({
        token,
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName,
          role: user.role,
        },
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Login failed" });
    }
  });

  // User profile routes
  app.get("/api/user/profile", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      res.json({
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        role: user.role,
        createdAt: user.createdAt,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/user/profile", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { fullName, password } = req.body;

      const updates: any = {};
      if (fullName) updates.fullName = fullName;
      if (password) updates.password = password;

      const user = await storage.updateUser(userId, updates);
      res.json({ message: "Profile updated successfully", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Search routes
  app.post("/api/search/query", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { query } = req.body;

      if (!query || !query.trim()) {
        return res.status(400).json({ message: "Query is required" });
      }

      const startTime = Date.now();

      // Check cache first — same query by this user in the last 24 hours
      const cached = await storage.findCachedSearch(userId, query);
      if (cached && cached.results) {
        const cachedResults = cached.results as any;
        return res.json({
          ...(typeof cachedResults === "object" ? cachedResults : {}),
          answer: cachedResults.answer,
          sourceType: cached.sourceType,
          extractedParams: cached.extractedParams,
          executionTime: cached.executionTime,
          cached: true,
          cachedAt: cached.createdAt,
        });
      }

      // Extract intent and classify domain in parallel
      const [extractedParams, domain] = await Promise.all([
        extractQueryIntent(query),
        classifyDomain(query),
      ]);

      if (domain !== "agriculture") {
        return res.status(400).json({
          message: "Currently only agriculture domain queries are supported. Please ask about crops, food prices, food security, or related topics.",
        });
      }

      // Fetch data from all sources in parallel, with timeout protection
      const [apiResults, userDocuments, userImages] = await Promise.all([
        withTimeout(fetchAgricultureData(extractedParams), 50000, "Agriculture API fetch"),
        storage.getUserDocuments(userId),
        storage.getUserImages(userId),
      ]);

      // Search in uploaded PDFs
      const pdfResults = userDocuments.length > 0
        ? await withTimeout(searchInDocuments(query, userDocuments), 30000, "Document search")
        : [];

      // Use already-analyzed image data
      const imageResults: string[] = userImages
        .slice(0, 3)
        .filter((img) => img.extractedData)
        .map((img) => img.extractedData as string);

      // Generate comprehensive AI response
      const answer = await withTimeout(
        generateAgricultureResponse(query, extractedParams, apiResults.map((r) => r.data), pdfResults, imageResults),
        35000,
        "Response generation"
      );

      let sourceType = "";
      if (apiResults.length > 0) sourceType += "API";
      if (pdfResults.length > 0) sourceType += sourceType ? "+PDF" : "PDF";
      if (imageResults.length > 0) sourceType += sourceType ? "+Image" : "Image";
      if (!sourceType) sourceType = "None";

      const responsePayload = {
        answer,
        apiResults: apiResults.map((r) => ({ source: r.source, data: r.data })),
        pdfResults,
        imageResults,
      };

      // Save to history
      await storage.createSearchHistory(
        insertSearchHistorySchema.parse({
          userId,
          query,
          extractedParams,
          sourceType,
          results: responsePayload,
          agentUsed: "Agriculture",
          executionTime: Date.now() - startTime,
        })
      );

      res.json({
        ...responsePayload,
        sourceType,
        extractedParams,
        executionTime: Date.now() - startTime,
        cached: false,
      });
    } catch (error: any) {
      console.error("Search error:", error.message);
      const isTimeout = error.message?.includes("timed out");
      res.status(isTimeout ? 504 : 500).json({
        message: isTimeout
          ? error.message
          : `Search failed: ${error.message || "An unexpected error occurred"}`,
      });
    }
  });

  app.get("/api/search/history", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const history = await storage.getUserSearchHistory(userId);
      res.json(history);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/search/history/:id", authMiddleware, async (req, res) => {
    try {
      await storage.deleteSearchHistory(req.params.id);
      res.json({ message: "History entry deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Document routes
  app.post("/api/documents/upload", authMiddleware, upload.single("file"), async (req: MulterRequest, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ message: "No file uploaded" });
      }

      if (req.file.mimetype !== "application/pdf") {
        await deleteFile(req.file.path);
        return res.status(400).json({ message: "Only PDF files are supported for document upload" });
      }

      const userId = (req as any).user.userId;
      const extractedText = await extractPdfText(req.file.path);

      if (!extractedText || extractedText.trim().length < 10) {
        return res.status(400).json({
          message: "Could not extract text from this PDF. The file may be scanned or image-based.",
        });
      }

      // Generate AI summary of the document
      const summary = await withTimeout(
        analyzePdfDocument(extractedText, req.file.originalname),
        35000,
        "PDF analysis"
      );

      const document = await storage.createDocument({
        userId,
        filename: req.file.originalname,
        filePath: req.file.path,
        extractedText,
        fileSize: req.file.size,
      });

      res.json({
        message: "Document uploaded and analyzed successfully",
        document,
        summary,
      });
    } catch (error: any) {
      console.error("Document upload error:", error.message);
      if (req.file?.path) {
        await deleteFile(req.file.path).catch(() => {});
      }
      const isTimeout = error.message?.includes("timed out");
      res.status(isTimeout ? 504 : 500).json({
        message: isTimeout ? error.message : `Upload failed: ${error.message}`,
      });
    }
  });

  // Ask a question about a specific document
  app.post("/api/documents/:id/ask", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { question } = req.body;

      if (!question || !question.trim()) {
        return res.status(400).json({ message: "Question is required" });
      }

      const doc = await storage.getDocument(req.params.id);
      if (!doc) {
        return res.status(404).json({ message: "Document not found" });
      }

      if (doc.userId !== userId) {
        return res.status(403).json({ message: "Access denied" });
      }

      if (!doc.extractedText) {
        return res.status(400).json({ message: "No text content available in this document" });
      }

      const answer = await withTimeout(
        askAboutDocument(doc.extractedText, doc.filename, question),
        30000,
        "Document Q&A"
      );

      res.json({ answer, documentName: doc.filename });
    } catch (error: any) {
      console.error("Document ask error:", error.message);
      const isTimeout = error.message?.includes("timed out");
      res.status(isTimeout ? 504 : 500).json({
        message: isTimeout ? error.message : `Failed to process question: ${error.message}`,
      });
    }
  });

  app.get("/api/documents/list", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const documents = await storage.getUserDocuments(userId);
      res.json(documents);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/documents/:id", authMiddleware, async (req, res) => {
    try {
      const doc = await storage.getDocument(req.params.id);
      if (doc) {
        await deleteFile(doc.filePath);
        await storage.deleteDocument(req.params.id);
      }
      res.json({ message: "Document deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Image routes
  app.post("/api/images/upload", authMiddleware, upload.single("file"), async (req: MulterRequest, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ message: "No file uploaded" });
      }

      const userId = (req as any).user.userId;

      const imageBuffer = await fs.readFile(req.file.path);
      const base64Image = imageBuffer.toString("base64");
      const dataUrl = `data:${req.file.mimetype};base64,${base64Image}`;

      const extractedData = await withTimeout(
        analyzeImage(dataUrl),
        30000,
        "Image analysis"
      );

      const image = await storage.createImage({
        userId,
        filename: req.file.originalname,
        filePath: req.file.path,
        extractedData,
        fileSize: req.file.size,
      });

      res.json({ message: "Image uploaded and analyzed successfully", image, analysis: extractedData });
    } catch (error: any) {
      console.error("Image upload error:", error.message);
      if (req.file?.path) {
        await deleteFile(req.file.path).catch(() => {});
      }
      const isTimeout = error.message?.includes("timed out");
      res.status(isTimeout ? 504 : 500).json({
        message: isTimeout ? error.message : `Image upload failed: ${error.message}`,
      });
    }
  });

  app.get("/api/images/list", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const images = await storage.getUserImages(userId);
      res.json(images);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/images/:id", authMiddleware, async (req, res) => {
    try {
      const img = await storage.getImage(req.params.id);
      if (img) {
        await deleteFile(img.filePath);
        await storage.deleteImage(req.params.id);
      }
      res.json({ message: "Image deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Admin routes
  app.get("/api/admin/dashboard", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const stats = await storage.getDashboardStats();
      res.json(stats);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/analytics", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const analytics = await storage.getQueryAnalytics();
      res.json(analytics);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/users", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const users = await storage.getAllUsers();
      res.json(
        users.map((u) => ({
          id: u.id,
          email: u.email,
          fullName: u.fullName,
          role: u.role,
          isActive: u.isActive,
          createdAt: u.createdAt,
        }))
      );
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/admin/users/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const { isActive } = req.body;
      const user = await storage.updateUser(req.params.id, { isActive });

      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: isActive ? "activate_user" : "deactivate_user",
        targetEntity: "user",
        targetId: req.params.id,
        details: { isActive },
      });

      res.json({ message: "User updated", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/admin/users/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.deleteUser(req.params.id);

      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "delete_user",
        targetEntity: "user",
        targetId: req.params.id,
        details: {},
      });

      res.json({ message: "User deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/admin/users", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const userData = insertUserSchema.parse(req.body);
      const existingUser = await storage.getUserByEmail(userData.email);

      if (existingUser) {
        return res.status(400).json({ message: "Email already exists" });
      }

      const user = await storage.createUser(userData);

      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "create_user",
        targetEntity: "user",
        targetId: user.id,
        details: { email: user.email },
      });

      res.json({ message: "User created", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/documents", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const documents = await storage.getAllDocuments();
      res.json(documents);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/images", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const images = await storage.getAllImages();
      res.json(images);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/logs", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const logs = await storage.getAllAdminLogs();
      res.json(logs);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/search-history", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const history = await storage.getAllSearchHistory();
      res.json(history);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/settings", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const settings = await storage.getAllApiSettings();
      res.json(settings);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/admin/settings", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const { keyName, keyValue, isActive } = req.body;

      const existing = await storage.getApiSetting(keyName);
      let setting;

      if (existing) {
        setting = await storage.updateApiSetting(keyName, { keyValue, isActive });
      } else {
        setting = await storage.createApiSetting(
          insertApiSettingSchema.parse({ keyName, keyValue, isActive })
        );
      }

      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "update_setting",
        targetEntity: "api_setting",
        targetId: setting?.id,
        details: { keyName },
      });

      res.json({ message: "Setting updated", setting });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Notification routes
  app.get("/api/admin/notifications", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const notifications = await storage.getAllNotifications();
      res.json(notifications);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/admin/notifications/clear", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.clearAllNotifications();
      res.json({ message: "All notifications cleared" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/admin/notifications/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.deleteNotification(req.params.id);
      res.json({ message: "Notification deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Global error handler
  app.use((err: any, _req: Request, res: any, _next: any) => {
    console.error("Unhandled error:", err);
    const status = err.status || err.statusCode || 500;
    const isTimeout = err.message?.includes("timed out");
    res.status(isTimeout ? 504 : status).json({
      message: err.message || "Internal Server Error",
    });
  });

  const httpServer = createServer(app);
  return httpServer;
}

import { useState, useRef, useEffect } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import { Send, Paperclip, FileText, Image, X, Loader2, AlertCircle, RefreshCw, Zap, Clock } from "lucide-react";
import type { SearchHistory } from "@shared/schema";

interface Message {
  id: string;
  type: "user" | "assistant" | "error";
  content: string;
  query?: string;
  results?: any;
  executionTime?: number;
  cached?: boolean;
  cachedAt?: string;
  attachments?: { type: "pdf" | "image"; name: string; id?: string; summary?: string }[];
  timestamp: Date;
  failedQuery?: string;
}

export default function ChatPage() {
  const { toast } = useToast();
  const [query, setQuery] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [attachments, setAttachments] = useState<File[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [conversationContext, setConversationContext] = useState<string>("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  const { data: history } = useQuery<SearchHistory[]>({
    queryKey: ["/api/search/history"],
  });

  useEffect(() => {
    const handleNewChat = () => {
      setMessages([]);
      setQuery("");
      setAttachments([]);
      setConversationContext("");
      initialized.current = true;
    };
    window.addEventListener("newChat", handleNewChat);
    return () => window.removeEventListener("newChat", handleNewChat);
  }, []);

  useEffect(() => {
    if (initialized.current) return;
    const activeConversation = localStorage.getItem("activeConversation");
    if (activeConversation) {
      try {
        const conversationData = JSON.parse(activeConversation);
        const results = conversationData.results as any;
        const loadedMessages: Message[] = [
          {
            id: `user-${conversationData.id}`,
            type: "user",
            content: conversationData.query,
            timestamp: new Date(conversationData.createdAt),
          },
          {
            id: `assistant-${conversationData.id}`,
            type: "assistant",
            content: results?.answer || "No response available",
            results,
            executionTime: conversationData.executionTime,
            timestamp: new Date(conversationData.createdAt),
          },
        ];
        setMessages(loadedMessages);
        setConversationContext(
          conversationData.query + " - " + (results?.answer || "").slice(0, 500)
        );
        localStorage.removeItem("activeConversation");
        initialized.current = true;
      } catch (e) {
        console.error("Failed to load conversation", e);
      }
    }
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const uploadFile = async (file: File) => {
    const formData = new FormData();
    formData.append("file", file);
    const isPDF = file.type === "application/pdf";
    const endpoint = isPDF ? "/api/documents/upload" : "/api/images/upload";
    const token = localStorage.getItem("token");
    const response = await fetch(endpoint, {
      method: "POST",
      headers: token ? { Authorization: `Bearer ${token}` } : {},
      body: formData,
    });
    if (!response.ok) {
      const err = await response.json().catch(() => ({ message: "Upload failed" }));
      throw new Error(err.message || "Upload failed");
    }
    return response.json();
  };

  const searchMutation = useMutation({
    mutationFn: async (searchQuery: string) => {
      const fullQuery = conversationContext
        ? `Follow-up question (previous context: ${conversationContext.slice(0, 300)}): ${searchQuery}`
        : searchQuery;
      return apiRequest("/api/search/query", {
        method: "POST",
        body: JSON.stringify({ query: fullQuery }),
      });
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/search/history"] });
      const assistantMessage: Message = {
        id: `assistant-${Date.now()}`,
        type: "assistant",
        content: data.answer || "I found some results for your query.",
        results: data,
        executionTime: data.executionTime,
        cached: data.cached,
        cachedAt: data.cachedAt,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, assistantMessage]);
      setConversationContext((prev) => (prev + " " + data.answer).slice(-1000));
    },
    onError: (error: any, variables) => {
      const errorMessage: Message = {
        id: `error-${Date.now()}`,
        type: "error",
        content: error.message || "Search failed. Please try again.",
        failedQuery: variables,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMessage]);
    },
  });

  const handleRetry = (failedQuery: string) => {
    setMessages((prev) => prev.filter((m) => m.type !== "error" || m.failedQuery !== failedQuery));
    searchMutation.mutate(failedQuery);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim() && attachments.length === 0) return;

    const uploadedAttachments: Message["attachments"] = [];

    if (attachments.length > 0) {
      setIsUploading(true);
      const uploadingMsg: Message = {
        id: `uploading-${Date.now()}`,
        type: "assistant",
        content: `Uploading and analyzing ${attachments.length} file(s) with Gemini AI...`,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, uploadingMsg]);

      try {
        for (const file of attachments) {
          const result = await uploadFile(file);
          const isPDF = file.type === "application/pdf";
          uploadedAttachments.push({
            type: isPDF ? "pdf" : "image",
            name: file.name,
            id: isPDF ? result.document?.id : result.image?.id,
            summary: result.summary || result.analysis,
          });
        }
        queryClient.invalidateQueries({ queryKey: ["/api/documents/list"] });
        queryClient.invalidateQueries({ queryKey: ["/api/images/list"] });

        // Remove the uploading message
        setMessages((prev) => prev.filter((m) => m.id !== uploadingMsg.id));
      } catch (error: any) {
        setMessages((prev) => prev.filter((m) => m.id !== uploadingMsg.id));
        const errMsg: Message = {
          id: `error-${Date.now()}`,
          type: "error",
          content: `File upload failed: ${error.message}`,
          timestamp: new Date(),
        };
        setMessages((prev) => [...prev, errMsg]);
        setIsUploading(false);
        setAttachments([]);
        return;
      }
      setIsUploading(false);
    }

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      type: "user",
      content: query || "Analyze uploaded files",
      attachments: uploadedAttachments.length > 0 ? uploadedAttachments : undefined,
      timestamp: new Date(),
    };
    setMessages((prev) => [...prev, userMessage]);
    setQuery("");
    setAttachments([]);

    if (uploadedAttachments.length > 0 && uploadedAttachments[0].summary) {
      const summaryMsg: Message = {
        id: `summary-${Date.now()}`,
        type: "assistant",
        content: uploadedAttachments[0].summary,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, summaryMsg]);
    } else if (uploadedAttachments.length > 0 && !query.trim()) {
      const assistantMessage: Message = {
        id: `assistant-${Date.now()}`,
        type: "assistant",
        content: `I've uploaded ${uploadedAttachments.length} file(s) successfully. You can now ask questions about these documents or images.`,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, assistantMessage]);
    }

    if (query.trim()) {
      searchMutation.mutate(query);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    const validFiles = files.filter((file) => {
      const isPDF = file.type === "application/pdf";
      const isImage = file.type.startsWith("image/");
      if (!isPDF && !isImage) {
        toast({ title: "Invalid file type", description: `${file.name} is not a PDF or image`, variant: "destructive" });
        return false;
      }
      if (file.size > 10 * 1024 * 1024) {
        toast({ title: "File too large", description: `${file.name} exceeds the 10MB limit`, variant: "destructive" });
        return false;
      }
      return true;
    });
    setAttachments((prev) => [...prev, ...validFiles]);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const removeAttachment = (index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  };

  const formatApiResults = (results: any) => {
    if (!results) return null;
    const apiResults = results.apiResults || [];
    const pdfResults = results.pdfResults || [];
    const imageResults = results.imageResults || [];
    const priceData = apiResults.find((api: any) => api.data?.currentPrice);
    const hasRealData = priceData && priceData.data?.currentPrice;

    if (!hasRealData && pdfResults.length === 0 && imageResults.length === 0) return null;

    return (
      <div className="mt-4 space-y-3">
        {hasRealData && (
          <div className="bg-emerald-50 dark:bg-emerald-900/20 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-3">
              <span className="text-lg">🌾</span>
              <span className="font-semibold text-emerald-700 dark:text-emerald-400">Market Data</span>
            </div>
            <div className="grid grid-cols-2 gap-3 text-sm">
              {priceData.data.crop && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Commodity</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">{priceData.data.crop}</p>
                </div>
              )}
              {priceData.data.country && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Location</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">{priceData.data.country}</p>
                </div>
              )}
              {priceData.data.currentPrice && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Current Price</p>
                  <p className="font-medium text-emerald-600 dark:text-emerald-400">
                    {priceData.data.currency || ""} {priceData.data.currentPrice.toLocaleString()}/{priceData.data.unit || "kg"}
                  </p>
                </div>
              )}
              {priceData.data.averagePrice && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Average Price</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">
                    {priceData.data.currency || ""} {priceData.data.averagePrice.toLocaleString()}/{priceData.data.unit || "kg"}
                  </p>
                </div>
              )}
              {priceData.data.lastUpdated && (
                <div className="col-span-2">
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Last Updated</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">
                    {new Date(priceData.data.lastUpdated).toLocaleDateString()}
                  </p>
                </div>
              )}
            </div>
          </div>
        )}
        {pdfResults.length > 0 && (
          <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-3">
            <div className="flex items-center gap-2 mb-1">
              <FileText className="w-4 h-4 text-blue-600" />
              <span className="font-semibold text-blue-700 dark:text-blue-400 text-sm">Document Insights</span>
            </div>
            <p className="text-xs text-gray-600 dark:text-gray-400">
              Found relevant content in {pdfResults.length} document(s)
            </p>
          </div>
        )}
        {imageResults.length > 0 && (
          <div className="bg-purple-50 dark:bg-purple-900/20 rounded-lg p-3">
            <div className="flex items-center gap-2 mb-1">
              <Image className="w-4 h-4 text-purple-600" />
              <span className="font-semibold text-purple-700 dark:text-purple-400 text-sm">Image Analysis</span>
            </div>
            <p className="text-xs text-gray-600 dark:text-gray-400">
              Analyzed {imageResults.length} image(s)
            </p>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] md:h-[calc(100vh-80px)] max-w-4xl mx-auto pb-16 md:pb-0">
      <div
        ref={chatContainerRef}
        className="flex-1 overflow-y-auto scrollbar-hide px-2 md:px-4 py-4 md:py-6 space-y-4 md:space-y-6"
      >
        {messages.length === 0 && (
          <div className="text-center py-16 space-y-6">
            <h1 className="text-3xl font-bold text-white" data-testid="heading-chat">
              What would you like to know?
            </h1>
            <p className="text-gray-400 max-w-lg mx-auto">
              Ask anything about agriculture, climate, or market data. Attach PDFs and images for AI-powered analysis.
            </p>
            <div className="flex flex-wrap gap-3 justify-center mt-8">
              {["Maize prices in Kenya", "Food security Ethiopia", "Wheat market trends"].map((suggestion) => (
                <button
                  key={suggestion}
                  onClick={() => setQuery(suggestion)}
                  className="px-4 py-2 bg-[#2a3749] hover:bg-[#3a4759] text-gray-300 rounded-full text-sm transition-colors"
                  data-testid={`button-suggestion-${suggestion}`}
                >
                  {suggestion}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((message) => {
          if (message.type === "error") {
            return (
              <div key={message.id} className="flex justify-start">
                <div className="max-w-[85%] bg-red-900/30 border border-red-500/40 rounded-2xl px-5 py-4">
                  <div className="flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-red-400 mt-0.5 shrink-0" />
                    <div className="flex-1">
                      <p className="text-red-300 text-sm">{message.content}</p>
                      {message.failedQuery && (
                        <button
                          onClick={() => handleRetry(message.failedQuery!)}
                          className="mt-2 flex items-center gap-1.5 text-xs text-red-400 hover:text-red-300 transition-colors"
                          data-testid="button-retry"
                        >
                          <RefreshCw className="w-3 h-3" />
                          Retry
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            );
          }

          return (
            <div
              key={message.id}
              className={`flex ${message.type === "user" ? "justify-end" : "justify-start"}`}
            >
              <div
                className={`max-w-[85%] rounded-2xl px-5 py-4 ${
                  message.type === "user"
                    ? "bg-emerald-500 text-white"
                    : "bg-[#2a3749] text-white"
                }`}
                data-testid={`message-${message.type}-${message.id}`}
              >
                {message.type === "assistant" && message.cached && (
                  <div className="flex items-center gap-1.5 mb-2 text-xs text-yellow-400/80">
                    <Zap className="w-3 h-3" />
                    <span>Cached response</span>
                    {message.cachedAt && (
                      <span className="text-gray-500">
                        · {new Date(message.cachedAt).toLocaleTimeString()}
                      </span>
                    )}
                  </div>
                )}

                {message.attachments && message.attachments.length > 0 && (
                  <div className="flex flex-wrap gap-2 mb-2">
                    {message.attachments.map((att, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-1 bg-white/20 rounded px-2 py-1 text-xs"
                      >
                        {att.type === "pdf" ? (
                          <FileText className="w-3 h-3" />
                        ) : (
                          <Image className="w-3 h-3" />
                        )}
                        {att.name}
                      </div>
                    ))}
                  </div>
                )}

                <p className="whitespace-pre-wrap leading-relaxed">{message.content}</p>

                {message.type === "assistant" && message.results && formatApiResults(message.results)}

                {message.executionTime !== undefined && (
                  <div className="flex items-center gap-1 mt-3 text-xs text-gray-400">
                    <Clock className="w-3 h-3" />
                    <span>
                      {message.cached
                        ? "Instant (cached)"
                        : `${(message.executionTime / 1000).toFixed(2)}s`}
                    </span>
                  </div>
                )}
              </div>
            </div>
          );
        })}

        {(searchMutation.isPending || isUploading) && (
          <div className="flex justify-start">
            <div className="bg-[#2a3749] rounded-2xl px-5 py-4 flex items-center gap-3">
              <Loader2 className="w-5 h-5 animate-spin text-emerald-400" />
              <span className="text-gray-300">
                {isUploading ? "Uploading & analyzing with Gemini..." : "Searching agriculture data..."}
              </span>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <div className="border-t border-[#3a4759] bg-[#1e293b] p-4">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-3">
            {attachments.map((file, idx) => (
              <div
                key={idx}
                className="flex items-center gap-2 bg-[#2a3749] rounded-lg px-3 py-2 text-sm text-white"
              >
                {file.type === "application/pdf" ? (
                  <FileText className="w-4 h-4 text-blue-400" />
                ) : (
                  <Image className="w-4 h-4 text-purple-400" />
                )}
                <span className="max-w-[150px] truncate">{file.name}</span>
                <button
                  onClick={() => removeAttachment(idx)}
                  className="hover:text-red-400 transition-colors"
                  data-testid={`button-remove-attachment-${idx}`}
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-center gap-3">
          <input
            ref={fileInputRef}
            type="file"
            accept=".pdf,image/jpeg,image/jpg,image/png"
            multiple
            onChange={handleFileSelect}
            className="hidden"
          />

          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={() => fileInputRef.current?.click()}
            className="text-gray-400 hover:text-white hover:bg-[#2a3749]"
            disabled={isUploading || searchMutation.isPending}
            title="Attach PDF or image"
            data-testid="button-attach-file"
          >
            <Paperclip className="w-5 h-5" />
          </Button>

          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Ask about agriculture data, or attach a PDF/image..."
            className="flex-1 bg-[#2a3749] border-[#3a4759] text-white h-12 placeholder:text-gray-500"
            disabled={searchMutation.isPending || isUploading}
            data-testid="input-chat-query"
          />

          <Button
            type="submit"
            size="icon"
            className="bg-emerald-500 hover:bg-emerald-600 h-12 w-12 shrink-0"
            disabled={searchMutation.isPending || isUploading || (!query.trim() && attachments.length === 0)}
            data-testid="button-send-message"
          >
            {isUploading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <Send className="w-5 h-5" />
            )}
          </Button>
        </form>
      </div>
    </div>
  );
}

